  "claim": {
    "component_id": "C042.component",
    "value": "Where practical, introduction of the selected change should preferably be staggered across comparable bookings.",
    "scope": "A qualified trial-design preference, not a requirement asserted to be practical in this depot.",
    "provenance": {
      "refs": [
