          "source_id": "P022",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the preference, comparable-booking condition and practicality qualification."
    }
  },
  "signal_basis": {
    "component_id": "C042.signal_basis",
    "value": "Repeated comparable observations of stage-specific delays inform trial selection. Measurements continue through a predefined trial period, while changing workload and concurrent interventions can distort temporal patterns.",
    "scope": "The candidate delays are assumed observed for this judgment. The recommendation concerns subsequent trial design; the mapping does not claim statistical proof or causal identification.",
